// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAwxTemplates AWX templates imported into the catalog
	// (GET /admin/awx/templates)
	ListAwxTemplates(w http.ResponseWriter, r *http.Request)
	// SyncAwxTemplates Import the AWX templates now, instead of waiting for the next sync
	// (POST /admin/awx/templates/sync)
	SyncAwxTemplates(w http.ResponseWriter, r *http.Request)
	// ReconcileIpam Compare EfficientIP with what rvav recorded
	// (GET /admin/ipam/reconcile)
	ReconcileIpam(w http.ResponseWriter, r *http.Request)
	// ListApprovals Approvals waiting for the caller, or decided by them
	// (GET /approvals)
	ListApprovals(w http.ResponseWriter, r *http.Request, params ListApprovalsParams)
	// GetApproval One approval level, with what an approver needs to decide
	// (GET /approvals/{approvalId})
	GetApproval(w http.ResponseWriter, r *http.Request, approvalId ApprovalIdPath)
	// DecideApproval Approve or reject
	// (POST /approvals/{approvalId}/decision)
	DecideApproval(w http.ResponseWriter, r *http.Request, approvalId ApprovalIdPath)
	// DelegateApproval Let another user decide this level
	// (POST /approvals/{approvalId}/delegate)
	DelegateApproval(w http.ResponseWriter, r *http.Request, approvalId ApprovalIdPath)
	// ListCatalogCategories Categories with the number of items the caller can request in a project
	// (GET /catalog/categories)
	ListCatalogCategories(w http.ResponseWriter, r *http.Request, params ListCatalogCategoriesParams)
	// ListCatalogItems Catalog items shared with a project, in their published version
	// (GET /catalog/items)
	ListCatalogItems(w http.ResponseWriter, r *http.Request, params ListCatalogItemsParams)
	// GetCatalogItem One catalog item
	// (GET /catalog/items/{itemId})
	GetCatalogItem(w http.ResponseWriter, r *http.Request, itemId ItemIdPath, params GetCatalogItemParams)
	// RemoveFavourite Remove an item from the caller's favourites
	// (DELETE /catalog/items/{itemId}/favourite)
	RemoveFavourite(w http.ResponseWriter, r *http.Request, itemId ItemIdPath)
	// AddFavourite Add an item to the caller's favourites
	// (PUT /catalog/items/{itemId}/favourite)
	AddFavourite(w http.ResponseWriter, r *http.Request, itemId ItemIdPath)
	// GetRequestForm The request form for an item version, ready to render
	// (GET /catalog/items/{itemId}/form)
	GetRequestForm(w http.ResponseWriter, r *http.Request, itemId ItemIdPath, params GetRequestFormParams)
	// ConsoleStream The web console's WebSocket, proxied to the ESXi host
	// (GET /console/{token})
	ConsoleStream(w http.ResponseWriter, r *http.Request, token string)
	// ListDeployments Deployments visible to the caller
	// (GET /deployments)
	ListDeployments(w http.ResponseWriter, r *http.Request, params ListDeploymentsParams)
	// GetDeployment One deployment with its resources
	// (GET /deployments/{deploymentId})
	GetDeployment(w http.ResponseWriter, r *http.Request, deploymentId string)
	// ListDeploymentActions The day-2 actions available on a deployment and its resources
	// (GET /deployments/{deploymentId}/actions)
	ListDeploymentActions(w http.ResponseWriter, r *http.Request, deploymentId DeploymentIdPath)
	// RunDeploymentAction Run a day-2 action
	// (POST /deployments/{deploymentId}/actions)
	RunDeploymentAction(w http.ResponseWriter, r *http.Request, deploymentId DeploymentIdPath, params RunDeploymentActionParams)
	// ListDeploymentHistory The requests that created and changed a deployment
	// (GET /deployments/{deploymentId}/history)
	ListDeploymentHistory(w http.ResponseWriter, r *http.Request, deploymentId DeploymentIdPath, params ListDeploymentHistoryParams)
	// OpenConsole Open a VM's console (ADR-0012)
	// (POST /deployments/{deploymentId}/resources/{resourceId}/console)
	OpenConsole(w http.ResponseWriter, r *http.Request, deploymentId DeploymentIdPath, resourceId string)
	// ListEnvironments Environments defined by administrators (for example dev, tst, prd)
	// (GET /environments)
	ListEnvironments(w http.ResponseWriter, r *http.Request)
	// StreamEvents Live updates as Server-Sent Events
	// (GET /events)
	StreamEvents(w http.ResponseWriter, r *http.Request, params StreamEventsParams)
	// ResolveFieldValues Resolve a field's dynamic options or computed value
	// (POST /forms/values)
	ResolveFieldValues(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user, their global roles and project memberships
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListProjects Projects the caller is a member of (all projects for administrators)
	// (GET /projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// GetProject One project
	// (GET /projects/{projectId})
	GetProject(w http.ResponseWriter, r *http.Request, projectId ProjectIdPath)
	// GetProjectQuota Quota limits and usage, for the whole project or one environment
	// (GET /projects/{projectId}/quota)
	GetProjectQuota(w http.ResponseWriter, r *http.Request, projectId ProjectIdPath, params GetProjectQuotaParams)
	// ListRequests Requests visible to the caller
	// (GET /requests)
	ListRequests(w http.ResponseWriter, r *http.Request, params ListRequestsParams)
	// CreateRequest Submit a request
	// (POST /requests)
	CreateRequest(w http.ResponseWriter, r *http.Request, params CreateRequestParams)
	// PreviewRequest Validate a draft and show what it would do, without creating anything
	// (POST /requests/preview)
	PreviewRequest(w http.ResponseWriter, r *http.Request)
	// GetRequest One request
	// (GET /requests/{requestId})
	GetRequest(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// ListRequestApprovals The approval levels of a request, with their decisions
	// (GET /requests/{requestId}/approvals)
	ListRequestApprovals(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// CancelRequest Cancel a request that is waiting or running
	// (POST /requests/{requestId}/cancel)
	CancelRequest(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// RetryRequest Run a failed request again from its failed step
	// (POST /requests/{requestId}/retry)
	RetryRequest(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// RollbackRequest Undo what a failed provisioning request created
	// (POST /requests/{requestId}/rollback)
	RollbackRequest(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// ListRequestSteps The request timeline, as a tree of steps
	// (GET /requests/{requestId}/steps)
	ListRequestSteps(w http.ResponseWriter, r *http.Request, requestId RequestIdPath)
	// GetStepLog Output of a step, such as an AWX job's stdout, read incrementally
	// (GET /requests/{requestId}/steps/{stepId}/log)
	GetStepLog(w http.ResponseWriter, r *http.Request, requestId RequestIdPath, stepId string, params GetStepLogParams)
}

